async def generate_monthly_client_performance_reports(reference_date: str | None = None, recipient_name: str = "Default User", recipient_email: str = "user@example.com", api_base: str = "http://127.0.0.1:8151", dry_run: bool = False, only_client_id: str | None = None) -> dict:
    """Generate and hand off monthly client campaign reports.

    Implements the canonical rules in guidance "Monthly client performance
    reporting and delivery rules". For each client it compares the last two
    complete months across Google Ads, Meta Ads, and Analytics; computes exact
    flags deterministically; uses an evidence-bounded LLM only for narrative
    drafting; and POSTs exactly one drafted or blocked payload. It never sends
    email or contacts a client. A real hand-off succeeds only when the endpoint
    returns HTTP 2xx and ``{"status": "received"}``.
    """
    import json
    import logging
    import re
    import urllib.parse
    import urllib.request
    from datetime import date
    from pydantic import BaseModel, Field

    log = logging.getLogger(__name__)

    class Narrative(BaseModel):
        what_happened: str
        why: str
        what_to_change: str
        email_subject: str
        email_body: str = Field(
            description="Internal-review email body only, with no greeting, sign-off, or placeholders"
        )

    Narrative.model_rebuild()

    if type(dry_run) is not bool:
        raise TypeError("dry_run must be a real bool; string values are rejected to prevent accidental delivery or suppression")

    def shift_month(year: int, month: int, delta: int) -> tuple[int, int]:
        index = year * 12 + month - 1 + delta
        return index // 12, index % 12 + 1

    def month_text(year: int, month: int) -> str:
        return f"{year:04d}-{month:02d}"

    def get_json(url: str):
        with urllib.request.urlopen(url, timeout=30) as response:
            return json.load(response)

    def post_delivery(url: str, payload: dict) -> dict:
        request = urllib.request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=30) as response:
            raw = response.read().decode("utf-8")
            result = json.loads(raw) if raw else {}
            if not 200 <= response.status < 300 or result.get("status") != "received":
                raise RuntimeError(
                    f"Delivery was not acknowledged: HTTP {response.status}, body={raw!r}"
                )
            return result

    def money(cents):
        return "—" if cents is None else f"${cents / 100:,.2f}"

    def ratio_change(current, previous):
        return None if previous in (None, 0) else (current - previous) / previous

    def percent(value):
        return "—" if value is None else f"{value:+.1%}"

    def cost_per_conversion(spend_cents, conversions):
        return None if not conversions else spend_cents / conversions

    def sentence(text: str) -> str:
        return " ".join(str(text).split())

    def markdown_cell(value) -> str:
        return str(value).replace("|", "\\|").replace("\n", " ")

    def clean_email_body(value: str) -> str:
        body = str(value or "").strip()
        body = re.sub(r"^\s*(hi|hello|dear)\b[^\n]*\n+", "", body, flags=re.IGNORECASE)
        body = re.sub(
            r"\n+\s*(best|thanks|thank you|regards|sincerely)[^\n]*(?:\n[^\n]*)?\s*$",
            "",
            body,
            flags=re.IGNORECASE,
        )
        body = re.sub(r"(?m)^.*\[[^\]]*(owner|name|agency)[^\]]*\].*\n?", "", body, flags=re.IGNORECASE)
        return body.strip()

    today = date.fromisoformat(reference_date) if reference_date else date.today()
    report_year, report_number = shift_month(today.year, today.month, -1)
    prior_year, prior_number = shift_month(today.year, today.month, -2)
    report_month = month_text(report_year, report_number)
    prior_month = month_text(prior_year, prior_number)
    base = api_base.rstrip("/")

    log.info("PHASE fetch_clients report_month=%s prior_month=%s", report_month, prior_month)
    clients = get_json(f"{base}/clients")
    if only_client_id:
        clients = [
            client
            for client in clients
            if str(client.get("client_id")) == str(only_client_id)
        ]
    if not clients:
        log.warning("SKIP no_clients only_client_id=%s", only_client_id)
        return {
            "report_month": report_month,
            "comparison_month": prior_month,
            "client_count": 0,
            "drafted": 0,
            "blocked": 0,
            "posted": 0,
            "dry_run": dry_run,
            "deliveries": [],
        }

    outcomes = []
    for index, client in enumerate(clients, 1):
        client_id = str(client["client_id"])
        client_name = str(client["name"])
        log.info(
            "PHASE client_start index=%s total=%s client_id=%s",
            index,
            len(clients),
            client_id,
        )
        notify(
            {
                "message": f"Preparing {report_month} report {index}/{len(clients)} for {client_name}."
            }
        )
        payload = {
            "client_id": client_id,
            "month": report_month,
            "status": "blocked",
            "blocked_reason": "",
            "flagged": [],
            "doc_markdown": "",
            "draft_email": {"to": recipient_email, "subject": "", "body": ""},
        }

        try:
            log.info("PHASE fetch_sources client_id=%s", client_id)
            raw = {}
            for platform in ("google_ads", "meta_ads", "analytics"):
                raw[platform] = {}
                for month in (prior_month, report_month):
                    encoded = urllib.parse.quote(client_id, safe="")
                    raw[platform][month] = get_json(
                        f"{base}/clients/{encoded}/{platform}?month={month}"
                    )

            analytics = {
                month: {
                    str(row["campaign_id"]): row
                    for row in raw["analytics"][month]
                }
                for month in (prior_month, report_month)
            }
            campaigns = []
            flags = []

            for platform in ("google_ads", "meta_ads"):
                prior_map = {
                    str(row["campaign_id"]): row
                    for row in raw[platform][prior_month]
                }
                current_map = {
                    str(row["campaign_id"]): row
                    for row in raw[platform][report_month]
                }
                for campaign_id in sorted(set(prior_map) | set(current_map)):
                    prior = prior_map.get(campaign_id, {})
                    current = current_map.get(campaign_id, {})
                    campaign_name = (
                        current.get("campaign")
                        or prior.get("campaign")
                        or campaign_id
                    )
                    prior_spend = int(prior.get("spend_cents") or 0)
                    current_spend = int(current.get("spend_cents") or 0)
                    prior_conversions = float(prior.get("conversions") or 0)
                    current_conversions = float(current.get("conversions") or 0)
                    prior_cpa = cost_per_conversion(
                        prior_spend, prior_conversions
                    )
                    current_cpa = cost_per_conversion(
                        current_spend, current_conversions
                    )
                    reasons = []

                    if (
                        current_spend >= prior_spend
                        and prior_conversions > 0
                        and current_conversions < prior_conversions * 2 / 3
                    ):
                        reasons.append(
                            f"Spend held steady or rose ({money(prior_spend)} to {money(current_spend)}) "
                            f"while conversions fell more than one-third ({prior_conversions:g} to {current_conversions:g})."
                        )
                    if prior_cpa is not None and current_cpa is not None:
                        cpa_change = (current_cpa - prior_cpa) / prior_cpa
                        if abs(cpa_change) > 0.40:
                            reasons.append(
                                f"Cost per conversion moved {cpa_change:+.1%} "
                                f"({money(prior_cpa)} to {money(current_cpa)})."
                            )
                    if current_spend > 20000 and current_conversions == 0:
                        reasons.append(
                            f"Spent {money(current_spend)} in {report_month} and recorded no conversions."
                        )
                    if reasons:
                        flags.append(
                            {
                                "campaign_id": campaign_id,
                                "platform": platform,
                                "reason": sentence(" ".join(reasons)),
                            }
                        )

                    prior_analytics = analytics[prior_month].get(campaign_id, {})
                    current_analytics = analytics[report_month].get(
                        campaign_id, {}
                    )
                    campaigns.append(
                        {
                            "campaign_id": campaign_id,
                            "campaign": campaign_name,
                            "platform": platform,
                            "previous": {
                                "spend_cents": prior_spend,
                                "impressions": int(prior.get("impressions") or 0),
                                "clicks": int(prior.get("clicks") or 0),
                                "conversions": prior_conversions,
                                "cost_per_conversion_cents": prior_cpa,
                                "revenue_cents": prior_analytics.get(
                                    "revenue_cents"
                                ),
                            },
                            "current": {
                                "spend_cents": current_spend,
                                "impressions": int(
                                    current.get("impressions") or 0
                                ),
                                "clicks": int(current.get("clicks") or 0),
                                "conversions": current_conversions,
                                "cost_per_conversion_cents": current_cpa,
                                "revenue_cents": current_analytics.get(
                                    "revenue_cents"
                                ),
                            },
                        }
                    )

            for campaign in campaigns:
                previous = campaign["previous"]
                current = campaign["current"]
                campaign["changes"] = {
                    key: ratio_change(current[key], previous[key])
                    if current[key] is not None and previous[key] is not None
                    else None
                    for key in (
                        "spend_cents",
                        "impressions",
                        "clicks",
                        "conversions",
                        "cost_per_conversion_cents",
                        "revenue_cents",
                    )
                }

            def totals(period: str) -> dict:
                total = {
                    "spend_cents": sum(
                        row[period]["spend_cents"] for row in campaigns
                    ),
                    "impressions": sum(
                        row[period]["impressions"] for row in campaigns
                    ),
                    "clicks": sum(row[period]["clicks"] for row in campaigns),
                    "conversions": sum(
                        row[period]["conversions"] for row in campaigns
                    ),
                    "revenue_cents": sum(
                        (row[period]["revenue_cents"] or 0)
                        for row in campaigns
                    )
                    if client.get("revenue_tracked")
                    else None,
                }
                total["cost_per_conversion_cents"] = cost_per_conversion(
                    total["spend_cents"], total["conversions"]
                )
                return total

            previous_totals = totals("previous")
            current_totals = totals("current")
            total_changes = {
                key: ratio_change(current_totals[key], previous_totals[key])
                if current_totals[key] is not None
                and previous_totals[key] is not None
                else None
                for key in previous_totals
            }
            evidence = {
                "client": client,
                "report_month": report_month,
                "comparison_month": prior_month,
                "totals": {
                    "previous": previous_totals,
                    "current": current_totals,
                    "changes": total_changes,
                },
                "flags": flags,
                "campaigns": campaigns,
            }

            log.info(
                "PHASE draft_narrative client_id=%s campaigns=%s flags=%s",
                client_id,
                len(campaigns),
                len(flags),
            )
            narrative = await query_llm(
                "Draft an internal monthly performance-report narrative and internal review email body using only this calculated evidence. "
                "Prioritize flagged campaigns. The three prose fields correspond to What happened, Why, and What we'd change. "
                "In Why, explicitly distinguish observed evidence from hypotheses and name checks needed; never claim an unobserved cause. "
                "The email body must start immediately with substantive content, contain no greeting, sign-off, or placeholders, and say it is a draft for review, not client-ready or sent.\n\n"
                + json.dumps(evidence, separators=(",", ":"), default=str),
                response_format=Narrative,
                model="openai/gpt-5.4-mini@openrouter",
                temperature=0.0,
            )
            if isinstance(narrative, dict):
                narrative = Narrative.model_validate(narrative)
            email_body = clean_email_body(narrative.email_body)
            if not email_body:
                raise ValueError("Narrative model returned an empty internal email body")

            flag_lines = ["## Flagged campaigns"]
            if flags:
                names = {
                    (row["campaign_id"], row["platform"]): row["campaign"]
                    for row in campaigns
                }
                for item in flags:
                    name = names[(item["campaign_id"], item["platform"])]
                    flag_lines.append(
                        f"- **{markdown_cell(name)}** ({item['platform']}, `{item['campaign_id']}`): {item['reason']}"
                    )
            else:
                flag_lines.append(
                    "No campaigns met the specified flagging thresholds."
                )

            summary_lines = [
                "## Account summary",
                f"| Metric | {prior_month} | {report_month} | Change |",
                "|---|---:|---:|---:|",
                f"| Spend | {money(previous_totals['spend_cents'])} | {money(current_totals['spend_cents'])} | {percent(total_changes['spend_cents'])} |",
                f"| Impressions | {previous_totals['impressions']:,} | {current_totals['impressions']:,} | {percent(total_changes['impressions'])} |",
                f"| Clicks | {previous_totals['clicks']:,} | {current_totals['clicks']:,} | {percent(total_changes['clicks'])} |",
                f"| Conversions | {previous_totals['conversions']:g} | {current_totals['conversions']:g} | {percent(total_changes['conversions'])} |",
                f"| Cost / conversion | {money(previous_totals['cost_per_conversion_cents'])} | {money(current_totals['cost_per_conversion_cents'])} | {percent(total_changes['cost_per_conversion_cents'])} |",
            ]
            if client.get("revenue_tracked"):
                summary_lines.append(
                    f"| Revenue | {money(previous_totals['revenue_cents'])} | {money(current_totals['revenue_cents'])} | {percent(total_changes['revenue_cents'])} |"
                )

            detail_lines = [
                "## Campaign comparison",
                f"| Platform | Campaign | Spend ({prior_month} → {report_month}) | Impressions Δ | Clicks Δ | Conversions ({prior_month} → {report_month}) | Cost / conv. ({prior_month} → {report_month}) | Revenue ({prior_month} → {report_month}) |",
                "|---|---|---:|---:|---:|---:|---:|---:|",
            ]
            flagged_keys = {
                (item["campaign_id"], item["platform"]) for item in flags
            }
            for row in sorted(
                campaigns,
                key=lambda item: (
                    (item["campaign_id"], item["platform"])
                    not in flagged_keys,
                    item["platform"],
                    item["campaign"],
                ),
            ):
                previous = row["previous"]
                current = row["current"]
                changes = row["changes"]
                revenue = (
                    f"{money(previous['revenue_cents'])} → {money(current['revenue_cents'])}"
                    if client.get("revenue_tracked")
                    else "Not tracked"
                )
                detail_lines.append(
                    f"| {row['platform']} | {markdown_cell(row['campaign'])} | "
                    f"{money(previous['spend_cents'])} → {money(current['spend_cents'])} ({percent(changes['spend_cents'])}) | "
                    f"{percent(changes['impressions'])} | {percent(changes['clicks'])} | "
                    f"{previous['conversions']:g} → {current['conversions']:g} ({percent(changes['conversions'])}) | "
                    f"{money(previous['cost_per_conversion_cents'])} → {money(current['cost_per_conversion_cents'])} ({percent(changes['cost_per_conversion_cents'])}) | {revenue} |"
                )

            document = "\n\n".join(
                [
                    f"# {client_name} — performance report for {report_month}",
                    f"Comparison: **{report_month} vs {prior_month}**. Money values are converted from integer cents. Campaign conversions and cost per conversion come from the ad platforms; revenue comes from Analytics where tracked.",
                    "\n".join(flag_lines),
                    "\n".join(summary_lines),
                    "## What happened\n" + narrative.what_happened.strip(),
                    "## Why\n" + narrative.why.strip(),
                    "## What we’d change\n" + narrative.what_to_change.strip(),
                    "\n".join(detail_lines),
                    "## Flagging rules used\n- Current-month spend was equal to or above the comparison month while conversions fell by more than one-third.\n- Cost per conversion changed by more than 40% when both months had at least one conversion.\n- Current-month spend exceeded $200 with zero conversions.",
                ]
            )
            payload.update(
                {
                    "status": "drafted",
                    "blocked_reason": "",
                    "flagged": flags,
                    "doc_markdown": document,
                    "draft_email": {
                        "to": recipient_email,
                        "subject": sentence(narrative.email_subject),
                        "body": f"Hi {recipient_name},\n\n{email_body}",
                    },
                }
            )
        except Exception as exc:
            log.exception("SOFT_FAIL client_report client_id=%s", client_id)
            payload["blocked_reason"] = sentence(
                f"Could not draft the {report_month} report for {client_name}: {type(exc).__name__}: {exc}"
            )

        try:
            if dry_run:
                acknowledgement = {"status": "dry_run"}
                posted = False
                log.info(
                    "SKIP dry_run_delivery client_id=%s status=%s",
                    client_id,
                    payload["status"],
                )
            else:
                log.info(
                    "PHASE post_delivery client_id=%s status=%s",
                    client_id,
                    payload["status"],
                )
                acknowledgement = post_delivery(
                    f"{base}/deliveries", payload
                )
                posted = True
                log.info(
                    "PHASE delivery_acknowledged client_id=%s", client_id
                )
            outcomes.append(
                {
                    "client_id": client_id,
                    "status": payload["status"],
                    "posted": posted,
                    "acknowledgement": acknowledgement,
                }
            )
        except Exception as delivery_error:
            log.exception("SOFT_FAIL delivery client_id=%s", client_id)
            outcomes.append(
                {
                    "client_id": client_id,
                    "status": payload["status"],
                    "posted": False,
                    "error": sentence(str(delivery_error)),
                }
            )

    drafted = sum(item["status"] == "drafted" for item in outcomes)
    blocked = sum(item["status"] == "blocked" for item in outcomes)
    posted = sum(bool(item.get("posted")) for item in outcomes)
    notify(
        {
            "message": f"Finished {report_month}: {drafted} drafted, {blocked} blocked, and {posted} acknowledged hand-offs out of {len(outcomes)} clients.",
            "completed": True,
        }
    )
    return {
        "report_month": report_month,
        "comparison_month": prior_month,
        "client_count": len(outcomes),
        "drafted": drafted,
        "blocked": blocked,
        "posted": posted,
        "dry_run": dry_run,
        "deliveries": outcomes,
    }
